import gallery from "../data/ddw27-gallery.json";

// The public DDW27 gallery (built in the Ask a Neuroscientist studio) shows each essay at
// tech-from-here-netherlands-field-ki.vercel.app/gallery/<id>, from its posting date and time on (Pacific/Honolulu).
// data/ddw27-gallery.json is generated by scripts/export_ddw27_gallery.py from the studio schedule; do not edit it by hand.
export type GalleryLink = { slug: string; gallery_url: string; posts_at: string; time_zone: string };

const links = gallery.posts as GalleryLink[];

export function galleryLink(accountKey: string, slug: string) {
  if (accountKey !== "ddw27") return undefined;
  return links.find((g) => g.slug === slug);
}
